mapper.select:
SELECT  
WHERE a.deleted_at IS NULL AND

 a.id IN #{id}
 a.account_group_id IN #{id}

ORDER BY a.id LIMIT #{limit}

mapper.sql:
task_id=#{taskId}
  AND status IN (3,4,5) AND tier_change IN (2,3,4)
  AND status IN (4,5) AND tier_change=5

mapper.select:
SELECT i.tenant_id,i.task_id,i.id AS item_id FROM account_tier_check_item i
INNER JOIN account_tier_check_task t ON t.id=i.task_id AND t.tenant_id=i.tenant_id
WHERE t.status=1 AND i.status=1 AND i.next_execute_at<=#{now}
ORDER BY i.updated_at,i.id LIMIT #{limit}
